    function testRegression_property() public {
        address bob = address(0x1234);
        vm.deal(address(this), 1 ether);
        payable(address(c)).transfer(1 ether);
        uint256 bobBalanceBefore = bob.balance;
        vm.prank(bob);
        bool ok;
        try c.withdrawAll(bob) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}
